                self._store.delete_sign_session(wallet_id, session_id)
                raise
    except CorruptDataError:
        raise
    except ValueError:
        # wallet_id 含非法字符（构造锁路径时抛出）
        raise ServiceError(400, "invalid wallet_id")
    return 201, self._session_view(self._peek_wallet(wallet_id), record)

def _peek_wallet(self, wallet_id: str) -> dict:
    """锁内已确认钱包存在；创建会话后重读钱包元数据以构造视图
    （正常情况下钱包必然仍在）。"""
    wallet = self._store.get_wallet(wallet_id)
    if wallet is None:  # pragma: no cover - 锁内不会消失
        raise ServiceError(404, f"wallet {wallet_id!r} not found")
    return wallet

